pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    address depositor = address(0xABCD);

    function setUp() public { c = new X_WALLET(address(new Log())); }

    // fuzzed params: amount to Collect, and initial deposit amount to put into account
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt) public {
        vm.assume(depositAmt <= VALUE_CAP);
        // Keep domain wide but sensible: ensure depositAmt and collectAmt fit in uint and dealable
        depositAmt = bound(depositAmt, 1, 10 ether); // deposit at least 1 wei up to 10 ether
        // collectAmt can be zero (this is the crucial case) up to depositAmt
        collectAmt = bound(collectAmt, 0, depositAmt);

        // Ensure depositAmt >= MinSum so account meets MinSum requirement when needed
        uint256 minSum = c.MinSum();
        vm.assume(depositAmt >= minSum);

        // fund depositor and perform Put to create balance and set unlockTime to past
        vm.deal(depositor, depositAmt);
        vm.startPrank(depositor);
        // Put with unlockTime = 0 so constructor logic sets unlockTime to block.timestamp
        c.Put{value: depositAmt}(0);
        // fast-forward time so unlockTime condition (block.timestamp > acc.unlockTime) holds
        vm.warp(block.timestamp + 1 hours);

        // Call Collect and capture whether it reverted
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // General invariant the reference satisfies for all admissible inputs:
        // If preconditions hold (depositAmt >= MinSum, depositAmt >= collectAmt, time passed)
        // then reference C does NOT revert even when collectAmt == 0 (it will perform the call which succeeds to an EOA).
        // The mutant, however, contains `if(_am==0) revert("zero amount");` and WILL revert when collectAmt == 0.
        // We therefore assert that when collectAmt == 0, the call MUST succeed (ok == true) per the reference.
        // This single assert passes on the reference for all admissible inputs and fails on the mutant for some input.
        if (collectAmt == 0) {
            assertTrue(ok);
        } else {
            // For non-zero amounts we do not force a specific outcome here; to keep the property universal
            // for the reference we only assert the guarantee for collectAmt == 0 which the mutant violates.
            assertTrue(true);
        }
    }
}

